CREATE TRIGGER jobs_metadata_delete AFTER DELETE ON jobs BEGIN
                DELETE FROM job_metadata WHERE id=OLD.id;
                DELETE FROM job_progress WHERE id=OLD.id;
                END

CREATE TRIGGER jobs_metadata_insert
                    AFTER INSERT ON jobs BEGIN
                    INSERT OR REPLACE INTO job_metadata VALUES
                    (NEW.id,json_remove(NEW.payload,'$.document','$.rolling_sources','$.refinement_history','$.fast_history','$.fast_previous_revision','$.boundary_candidate','$.boundary_candidates','$.rolling_inflight','$.fast_retained_candidate'),json_extract(NEW.payload,'$.status'),json_extract(NEW.payload,'$.created'));
                    DELETE FROM job_progress WHERE id=NEW.id;
                    END

CREATE TRIGGER jobs_metadata_update
                    AFTER UPDATE ON jobs BEGIN
                    INSERT OR REPLACE INTO job_metadata VALUES
                    (NEW.id,json_remove(NEW.payload,'$.document','$.rolling_sources','$.refinement_history','$.fast_history','$.fast_previous_revision','$.boundary_candidate','$.boundary_candidates','$.rolling_inflight','$.fast_retained_candidate'),json_extract(NEW.payload,'$.status'),json_extract(NEW.payload,'$.created'));
                    DELETE FROM job_progress WHERE id=NEW.id;
                    END
